public Resultado Compartilhar(Documento? documento, string? email)
{
    if (documento == null)
        return Resultado.Falha("Documento não encontrado");

    if (string.IsNullOrWhiteSpace(email))
        return Resultado.Falha("Informe o e-mail");

    if (documento.Excluido)
        return Resultado.Falha("Documento na lixeira");

    return Resultado.Ok($"Enviado para {email}");
}

// 1) Compartilhar(null, "ana@x.com")                          → Falha "Documento não encontrado" (exemplo)
// 2) Compartilhar(doc { Excluido = true }, "")
// 3) Compartilhar(doc { Excluido = false }, "ana@x.com")

public Resultado EnviarMensagem(Conversa? conversa, string texto)
{
    if (conversa != null)
    {
        if (conversa.Aberta)
        {
            if (texto.Length <= 1000)
            {
                conversa.Mensagens.Add(texto);
                return Resultado.Ok("Mensagem enviada");
            }
            else
            {
                return Resultado.Falha("Mensagem muito longa");
            }
        }
        else
        {
            return Resultado.Falha("Conversa encerrada");
        }
    }
    else
    {
        return Resultado.Falha("Conversa não encontrada");
    }
}

